#include <iostream>
#include <vector>
#include <cstring>
#include <algorithm>
using namespace std;

const int MOD = 1000000007;

long long mod_exp(long long base, long long exp) {
    long long res = 1;
    base %= MOD;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return res;
}

vector<int> trios;
int p[10][10];
long long f[1 << 20], g[1 << 20];

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) {
            int x;
            cin >> x;
            p[i][j] = (int)((long long)x * mod_exp(100, MOD - 2) % MOD);
        }

    for (int i = n; i <= 5; ++i) p[i][i] = 1;

    for (int m = 0; m < 64; ++m)
        if (__builtin_popcount(m) == 3)
            trios.push_back(m);

    for (int mask = 0; mask < (1 << 18); ++mask) {
        bool grid[6][6] = {};
        long long prod = 1;
        int idx = 0;

        for (int r = 0; r < 6; ++r)
            for (int c = 0; c <= 2; ++c) {
                if (mask & (1 << idx)) {
                    grid[r][c] = true;
                    prod = (prod * p[r][c]) % MOD;
                } else {
                    prod = (prod * ((1 - p[r][c] + MOD) % MOD)) % MOD;
                }
                ++idx;
            }

        int comb_mask = 0;
        for (int t = 0; t < (int)trios.size(); ++t) {
            int combo = trios[t];
            int a[3], cnt = 0;
            for (int k = 0; k < 6; ++k)
                if (combo & (1 << k)) a[cnt++] = k;

            if ((grid[a[0]][0] && grid[a[1]][1] && grid[a[2]][2]) ||
                (grid[a[0]][0] && grid[a[2]][1] && grid[a[1]][2]) ||
                (grid[a[1]][0] && grid[a[0]][1] && grid[a[2]][2]) ||
                (grid[a[1]][0] && grid[a[2]][1] && grid[a[0]][2]) ||
                (grid[a[2]][0] && grid[a[0]][1] && grid[a[1]][2]) ||
                (grid[a[2]][0] && grid[a[1]][1] && grid[a[0]][2]))
                comb_mask |= (1 << t);
        }

        f[comb_mask] = (f[comb_mask] + prod) % MOD;
    }

    for (int mask = 0; mask < (1 << 18); ++mask) {
        bool grid[6][6] = {};
        long long prod = 1;
        int idx = 0;

        for (int r = 0; r < 6; ++r)
            for (int c = 3; c <= 5; ++c) {
                if (mask & (1 << idx)) {
                    grid[r][c] = true;
                    prod = (prod * p[r][c]) % MOD;
                } else {
                    prod = (prod * ((1 - p[r][c] + MOD) % MOD)) % MOD;
                }
                ++idx;
            }

        int comb_mask = 0;
        for (int t = 0; t < (int)trios.size(); ++t) {
            int combo = trios[t];
            int comp = combo ^ 63;
            int a[3], cnt = 0;
            for (int k = 0; k < 6; ++k)
                if (comp & (1 << k)) a[cnt++] = k;

            if ((grid[a[0]][3] && grid[a[1]][4] && grid[a[2]][5]) ||
                (grid[a[0]][3] && grid[a[2]][4] && grid[a[1]][5]) ||
                (grid[a[1]][3] && grid[a[0]][4] && grid[a[2]][5]) ||
                (grid[a[1]][3] && grid[a[2]][4] && grid[a[0]][5]) ||
                (grid[a[2]][3] && grid[a[0]][4] && grid[a[1]][5]) ||
                (grid[a[2]][3] && grid[a[1]][4] && grid[a[0]][5]))
                comb_mask |= (1 << t);
        }

        g[comb_mask] = (g[comb_mask] + prod) % MOD;
    }

    for (int b = 0; b < 20; ++b)
        for (int m = (1 << 20) - 1; m >= 0; --m)
            if (m & (1 << b))
                g[m] = (g[m] + g[m ^ (1 << b)]) % MOD;

    long long ans = 0;
    for (int m = 0; m < (1 << 20); ++m)
        ans = (ans + f[m] * g[((1 << 20) - 1) ^ m]) % MOD;

    cout << (1 - ans + MOD) % MOD << '\n';
    return 0;
}
